import React, { useState, useRef, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import ReCAPTCHA from "react-google-recaptcha";
import { useAuth } from "../AuthContext";
import { doc, getDoc } from "firebase/firestore";
import { db } from "../firebase";
import * as OTPAuth from "otpauth";

const RECAPTCHA_SITE_KEY = "6LfSZPQsAAAAAAAVs-GwPeTbw-OdFpss3JA-rk5f";

// ── UI Taraflı Rate Limiting ─────────────────────────────────────────────────
// Gerçek rate limiting backend (Firebase Functions) tarafında yapılmalıdır.
// Bu kısım ek bir önlem olarak tarayıcı tarafında çalışır.
// localStorage kullanıldığı için sayfa yenilemesine karşı dayanıklıdır
// fakat incognito modu veya localStorage temizleme ile aşılabilir.
const RL_KEY        = "login_attempts";
const MAX_ATTEMPTS  = 5;       // kaç başarısız denemede kilitlensin
const LOCKOUT_MS    = 15 * 60 * 1000; // 15 dakika

function getRLData() {
  try {
    return JSON.parse(localStorage.getItem(RL_KEY)) || { count: 0, lockedUntil: 0 };
  } catch { return { count: 0, lockedUntil: 0 }; }
}
function setRLData(data) {
  localStorage.setItem(RL_KEY, JSON.stringify(data));
}
function recordFailedAttempt() {
  const data = getRLData();
  const count = data.count + 1;
  const lockedUntil = count >= MAX_ATTEMPTS ? Date.now() + LOCKOUT_MS : data.lockedUntil;
  setRLData({ count, lockedUntil });
  return { count, lockedUntil };
}
function resetAttempts() {
  setRLData({ count: 0, lockedUntil: 0 });
}
function getLockoutRemaining() {
  const { lockedUntil } = getRLData();
  return Math.max(0, lockedUntil - Date.now());
}

export default function Login() {
  const [email, setEmail]         = useState("");
  const [password, setPassword]   = useState("");
  const [error, setError]         = useState("");
  const [loading, setLoading]     = useState(false);
  const [show2FA, setShow2FA]     = useState(false);
  const [twoFACode, setTwoFACode] = useState("");
  const [secret, setSecret]       = useState("");
  const [captchaToken, setCaptchaToken] = useState(null);

  // Rate limiting state
  const [lockoutRemaining, setLockoutRemaining] = useState(getLockoutRemaining());
  const [attemptCount, setAttemptCount]         = useState(getRLData().count);
  const lockoutTimerRef = useRef(null);

  const recaptchaRef = useRef(null);
  const { login, setAwaitingTwoFA } = useAuth();
  const navigate = useNavigate();

  // Kilit geri sayım sayacı
  useEffect(() => {
    if (lockoutRemaining <= 0) return;
    lockoutTimerRef.current = setInterval(() => {
      const rem = getLockoutRemaining();
      setLockoutRemaining(rem);
      if (rem <= 0) {
        clearInterval(lockoutTimerRef.current);
        resetAttempts();
        setAttemptCount(0);
        setError("");
      }
    }, 1000);
    return () => clearInterval(lockoutTimerRef.current);
  }, [lockoutRemaining]);

  const formatTime = (ms) => {
    const secs = Math.ceil(ms / 1000);
    const m = Math.floor(secs / 60);
    const s = secs % 60;
    return m > 0 ? `${m}:${String(s).padStart(2, "0")}` : `${s}s`;
  };

  async function handleSubmit(e) {
    e.preventDefault();
    e.stopPropagation();
    setError("");

    // Rate limit kontrolü
    const remaining = getLockoutRemaining();
    if (remaining > 0) {
      setError(`Çok fazla başarısız deneme. Lütfen ${formatTime(remaining)} bekleyin.`);
      return;
    }

    if (!captchaToken) {
      setError("Lütfen önce robot olmadığını doğrula.");
      return;
    }

    setLoading(true);
    setAwaitingTwoFA(true);

    try {
      const result = await login(email, password);

      // E-posta doğrulanmamışsa girişi engelle
      if (!result.user.emailVerified) {
        await result.user.reload(); // güncel durumu çek
        if (!result.user.emailVerified) {
          setAwaitingTwoFA(false);
          recaptchaRef.current?.reset();
          setCaptchaToken(null);
          setError("E-posta adresin henüz doğrulanmamış. Gelen kutunu kontrol et.");
          setLoading(false);
          return;
        }
      }

      const ref    = doc(db, "users", result.user.uid);
      const snap   = await getDoc(ref);

      // Başarılı giriş — deneme sayacını sıfırla
      resetAttempts();
      setAttemptCount(0);

      if (snap.exists() && snap.data().twoFAEnabled) {
        setSecret(snap.data().twoFASecret);
        setShow2FA(true);
        setLoading(false);
      } else {
        setAwaitingTwoFA(false);
        navigate("/dashboard");
      }
    } catch (err) {
      setAwaitingTwoFA(false);
      recaptchaRef.current?.reset();
      setCaptchaToken(null);

      // Başarısız denemeyi kaydet
      const { count, lockedUntil } = recordFailedAttempt();
      setAttemptCount(count);

      if (lockedUntil > Date.now()) {
        setLockoutRemaining(getLockoutRemaining());
        setError(`${MAX_ATTEMPTS} başarısız deneme. Hesap ${formatTime(LOCKOUT_MS)} süreyle kilitlendi.`);
        setLoading(false);
        return;
      }

      const msgs = {
        "auth/user-not-found":    "Bu e-posta ile kayıtlı kullanıcı bulunamadı.",
        "auth/wrong-password":    "Şifre yanlış, tekrar deneyin.",
        "auth/invalid-email":     "Geçersiz e-posta adresi.",
        "auth/too-many-requests": "Çok fazla deneme. Lütfen bekleyin.",
        "auth/invalid-credential":"E-posta veya şifre hatalı.",
      };
      const remaining = MAX_ATTEMPTS - count;
      const base = msgs[err.code] || "Giriş yapılamadı.";
      setError(remaining > 0 ? `${base} (${remaining} deneme hakkı kaldı)` : base);
      setLoading(false);
    }
  }

  // 2FA doğrulama
  function verify2FA() {
    const totp  = new OTPAuth.TOTP({ secret, digits: 6 });
    const delta = totp.validate({ token: twoFACode, window: 1 });
    if (delta !== null) {
      setAwaitingTwoFA(false);
      navigate("/dashboard");
    } else {
      setError("Kod yanlış, tekrar dene.");
    }
  }

  // 2FA ekranı
  if (show2FA) {
    return (
      <div className="auth-container">
        <div className="auth-card">
          <div className="auth-header">
            <div className="auth-logo">🔐</div>
            <h1>2FA Doğrulama</h1>
            <p>Authenticator uygulamanındaki 6 haneli kodu gir</p>
          </div>
          {error && <div className="auth-error">{error}</div>}
          <div className="auth-form">
            <div className="form-group">
              <label>Doğrulama Kodu</label>
              <input type="text" placeholder="000000" maxLength={6} value={twoFACode}
                onChange={e => setTwoFACode(e.target.value)}
                onKeyDown={e => e.key === "Enter" && verify2FA()}
                autoFocus
                style={{ letterSpacing:"0.2em", fontFamily:"monospace", fontSize:"1.2rem", textAlign:"center" }}
              />
            </div>
            <button className="auth-btn" onClick={verify2FA}>Doğrula ve Giriş Yap</button>
          </div>
        </div>
      </div>
    );
  }

  const isLocked = lockoutRemaining > 0;

  return (
    <div className="auth-container">
      <div className="auth-card">
        <div className="auth-header">
          <div className="auth-logo">⬡</div>
          <h1>Tekrar hoşgeldin</h1>
          <p>Hesabına giriş yap</p>
        </div>

        {/* Kilit uyarısı */}
        {isLocked && (
          <div className="auth-error" style={{ background:"rgba(239,68,68,0.12)",border:"1px solid rgba(239,68,68,0.4)",borderRadius:"10px",padding:"0.85rem 1rem",marginBottom:"1rem",textAlign:"center" }}>
            <div style={{ fontSize:"1.5rem",marginBottom:"0.3rem" }}>🔒</div>
            <strong>Hesap Geçici Olarak Kilitlendi</strong>
            <div style={{ marginTop:"0.35rem",fontSize:"0.85rem" }}>
              Kalan süre: <strong style={{ fontFamily:"monospace",color:"#fbbf24" }}>{formatTime(lockoutRemaining)}</strong>
            </div>
          </div>
        )}

        {/* Deneme uyarısı (kilitli değil ama deneme hakkı azalıyor) */}
        {!isLocked && attemptCount > 0 && (
          <div style={{ background:"rgba(251,191,36,0.08)",border:"1px solid rgba(251,191,36,0.3)",borderRadius:"10px",padding:"0.65rem 1rem",marginBottom:"0.75rem",fontSize:"0.82rem",color:"#fde68a",textAlign:"center" }}>
            ⚠️ {MAX_ATTEMPTS - attemptCount} başarısız deneme hakkın kaldı
          </div>
        )}

        {error && !isLocked && <div className="auth-error">{error}</div>}

        <form onSubmit={handleSubmit} className="auth-form">
          <div className="form-group">
            <label>E-posta</label>
            <input type="email" placeholder="ornek@mail.com" value={email}
              onChange={e => setEmail(e.target.value)} required disabled={isLocked} />
          </div>
          <div className="form-group">
            <label>Şifre</label>
            <input type="password" placeholder="••••••••" value={password}
              onChange={e => setPassword(e.target.value)} required disabled={isLocked} />
          </div>

          <div style={{ display:"flex", justifyContent:"center", margin:"0.75rem 0" }}>
            <ReCAPTCHA
              ref={recaptchaRef}
              sitekey={RECAPTCHA_SITE_KEY}
              onChange={token => setCaptchaToken(token)}
              onExpired={() => setCaptchaToken(null)}
              theme="dark"
            />
          </div>

          <button type="submit" className="auth-btn" disabled={loading || !captchaToken || isLocked}>
            {loading ? <span className="spinner" /> : isLocked ? `🔒 ${formatTime(lockoutRemaining)}` : "Giriş Yap"}
          </button>
        </form>

        <p className="auth-switch">
          Hesabın yok mu? <Link to="/register">Kayıt ol</Link>
        </p>
      </div>
    </div>
  );
}
